mapper.select:
SELECT

FROM workbench_evaluations e
JOIN workbench_prompt_revisions r ON r.uuid = e.revision_ref_uuid
WHERE e.organization_uuid = #{organizationUUID}
AND r.revision_uuid = #{revisionUUID}
ORDER BY e.created_at ASC, e.uuid ASC

SELECT

FROM workbench_evaluations e
WHERE e.organization_uuid = #{organizationUUID}
AND e.evaluation_uuid = #{evaluationUUID}
LIMIT 1

mapper.delete:
DELETE FROM workbench_evaluations e
WHERE e.organization_uuid = #{organizationUUID}
AND e.evaluation_uuid = #{evaluationUUID}
RETURNING
